{
  "package_format": "tin-workflow-package-v1",
  "definition": {
    "key": "product.analytics_brief",
    "title": "Product analytics brief",
    "description": "A standing evidence-based analytics brief for the connected project.",
    "version": "1.0.0",
    "executor": "codex.procedure",
    "schedule_modes": [
      "on_demand",
      "daily",
      "weekly"
    ],
    "input_schema": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "project_id": {
          "type": "string",
          "format": "uuid"
        },
        "posthog_project_id": {
          "type": "string",
          "minLength": 1,
          "maxLength": 20,
          "title": "PostHog project ID"
        },
        "start_date": {
          "type": "string",
          "format": "date",
          "title": "Start date (UTC, inclusive)",
          "maxLength": 10
        },
        "end_date": {
          "type": "string",
          "format": "date",
          "title": "End date (UTC, exclusive)",
          "maxLength": 10
        },
        "exclusions": {
          "type": "string",
          "maxLength": 2000,
          "default": "",
          "title": "Explicit population exclusions"
        }
      },
      "required": [
        "project_id",
        "posthog_project_id",
        "start_date",
        "end_date"
      ]
    },
    "integration_requirements": [
      {
        "provider_key": "custom.api.posthog",
        "capabilities": [
          "http.read",
          "http.write"
        ],
        "required": true
      }
    ],
    "procedure": {
      "prompt_path": "PROMPT.md",
      "skills_path": "skills",
      "skill_files": [
        "skills/analytics-brief/SKILL.md"
      ],
      "entry_skill": "analytics-brief",
      "workspace": {
        "kind": "project.state"
      },
      "sandbox": {
        "profile": "isolated",
        "egress": "fenced",
        "timeout_seconds": 900
      },
      "services": {
        "analytics": {
          "provider_key": "custom.api.posthog",
          "max_calls": 8,
          "max_response_bytes": 32000
        }
      },
      "output": {
        "kind": "project.artifact",
        "path": "reports/PRODUCT_ANALYTICS.md",
        "media_type": "text/markdown",
        "max_bytes": 32000
      }
    },
    "presentation": {
      "flow": {
        "direction": "TD",
        "nodes": [
          {
            "id": "posthog",
            "kind": "surface",
            "label": "Your PostHog project",
            "fact": "at most 8 read-only calls, 32 KB each"
          },
          {
            "id": "definitions",
            "kind": "step",
            "label": "Read the event definitions",
            "fact": "before any query, never inferred"
          },
          {
            "id": "sections",
            "kind": "step",
            "label": "Query the five sections",
            "fact": "ordered funnels in SQL, checked in Python"
          },
          {
            "id": "brief",
            "kind": "receipt",
            "label": "Analytics brief in Files",
            "fact": "reports/PRODUCT_ANALYTICS.md, no advice"
          }
        ],
        "edges": [
          {
            "from": "posthog",
            "to": "definitions",
            "kind": "call"
          },
          {
            "from": "definitions",
            "to": "sections",
            "kind": "call"
          },
          {
            "from": "sections",
            "to": "brief",
            "kind": "call"
          }
        ]
      }
    }
  }
}
